# =============================================================================\r\n# run_label_ratio_experiments.ps1\r\n# =============================================================================\r\n# Runs training + evaluation across multiple labeled data ratios\r\n# (5%, 10%, 20%, 50%, 100%) for all datasets and tasks.\r\n#\r\n# This generates results for the \"Labeled Data Sensitivity\" table in your paper.\r\n#\r\n# Usage:\r\n#   .\\run_label_ratio_experiments.ps1\r\n#   .\\run_label_ratio_experiments.ps1 -datasets @(\"cicids2017\")          # single dataset\r\n#   .\\run_label_ratio_experiments.ps1 -ratios @(0.05, 0.20)              # specific ratios\r\n#   .\\run_label_ratio_experiments.ps1 -datasets @(\"cicids2017\") -tasks @(\"dos\")  # single task\r\n# =============================================================================\r\n\r\nparam (\r\n    [double[]]$ratios = @(0.05, 0.10, 0.20, 0.50, 1.0),\r\n    [string[]]$datasets = @(\"cicids2017\", \"kddcup99\", \"unsw\"),\r\n    [string[]]$tasks = @(\"intrusion\", \"dos\", \"port_scan\"),\r\n    [int]$task_epochs = 20,\r\n    [int]$gpm_epochs = 10\r\n)\r\n\r\n$ErrorActionPreference = \"Stop\"\r\n\r\n# Ensure we are in the ids-system directory\r\n$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path\r\nif ($null -ne $scriptDir -and $scriptDir -ne \"\") {\r\n    Set-Location $scriptDir\r\n}\r\n\r\n# Check if venv is active\r\nif ($null -eq $env:VIRTUAL_ENV) {\r\n    if (Test-Path \".\\.venv\\Scripts\\Activate.ps1\") {\r\n        Write-Host \"Activating virtual environment...\" -ForegroundColor Cyan\r\n        . .\\.venv\\Scripts\\Activate.ps1\r\n    } else {\r\n        Write-Warning \"No virtual environment found at .\\.venv. Using system python.\"\r\n    }\r\n}\r\n\r\n# Results collector\r\n$allResults = @()\r\n$resultsDir = \"./logs/label_ratio_experiments\"\r\nNew-Item -ItemType Directory -Force -Path $resultsDir | Out-Null\r\n\r\n# Dataset-specific configurations\r\n$datasetConfigs = @{\r\n    \"cicids2017\" = @{\r\n        \"ssl_args\" = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col Label\"\r\n        \"intrusion\" = @{\r\n            \"train_args\" = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col Label\"\r\n            \"eval_args\"  = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col Label\"\r\n        }\r\n        \"dos\" = @{\r\n            \"train_args\" = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col AttackCategory\"\r\n            \"eval_args\"  = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col AttackCategory\"\r\n        }\r\n        \"port_scan\" = @{\r\n            \"train_args\" = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col AttackCategory\"\r\n            \"eval_args\"  = \"--dataset cicids2017 --data_path ../CICIDS2017 --label_col AttackCategory\"\r\n        }\r\n    }\r\n    \"kddcup99\" = @{\r\n        \"ssl_args\" = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col Label\"\r\n        \"intrusion\" = @{\r\n            \"train_args\" = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col Label\"\r\n            \"eval_args\"  = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col Label\"\r\n        }\r\n        \"dos\" = @{\r\n            \"train_args\" = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col AttackCategory\"\r\n            \"eval_args\"  = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col AttackCategory\"\r\n        }\r\n        \"port_scan\" = @{\r\n            \"train_args\" = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col AttackCategory\"\r\n            \"eval_args\"  = \"--dataset kddcup99 --data_path ../KDDCUP99 --label_col AttackCategory\"\r\n        }\r\n    }\r\n    \"unsw\" = @{\r\n        \"ssl_args\" = \"--train_csv ../IDS-UNSW_NB/UNSW_NB15_training-set.csv --label_col label\"\r\n        \"intrusion\" = @{\r\n            \"train_args\" = \"--train_csv ../IDS-UNSW_NB/UNSW_NB15_training-set.csv --label_col label\"\r\n            \"eval_args\"  = \"--task intrusion --test_csv ../IDS-UNSW_NB/UNSW_NB15_testing-set.csv --label_col label\"\r\n        }\r\n        \"dos\" = @{\r\n            \"train_args\" = \"--train_csv ../IDS-UNSW_NB/UNSW_NB15_training-set.csv --label_col attack_cat\"\r\n            \"eval_args\"  = \"--task dos --test_csv ../IDS-UNSW_NB/UNSW_NB15_testing-set.csv --label_col attack_cat\"\r\n        }\r\n        \"port_scan\" = @{\r\n            \"train_args\" = \"--train_csv ../IDS-UNSW_NB/UNSW_NB15_training-set.csv --label_col attack_cat\"\r\n            \"eval_args\"  = \"--task port_scan --test_csv ../IDS-UNSW_NB/UNSW_NB15_testing-set.csv --label_col attack_cat\"\r\n        }\r\n    }\r\n}\r\n\r\nforeach ($dataset in $datasets) {\r\n    $config = $datasetConfigs[$dataset]\r\n    \r\n    # SSL encoder is shared across all ratios — no need to retrain\r\n    $encoderPath = \"checkpoints/$dataset/encoder_frozen.keras\"\r\n    if (-not (Test-Path $encoderPath)) {\r\n        Write-Host \"`n[SSL] Encoder not found for $dataset. You must run SSL pretraining first!\" -ForegroundColor Red\r\n        Write-Host \"  Run: .\\run_all.ps1 -datasets @('$dataset') -retrain `$true\" -ForegroundColor Yellow\r\n        continue\r\n    }\r\n    Write-Host \"`n[INFO] Using existing SSL encoder for $dataset\" -ForegroundColor Green\r\n\r\n    foreach ($ratio in $ratios) {\r\n        $ratioPercent = [int]($ratio * 100)\r\n        $ratioTag = \"lr${ratioPercent}\"\r\n        \r\n        Write-Host \"`n========================================================\" -ForegroundColor Cyan\r\n        Write-Host \"  EXPERIMENT: $dataset | Label Ratio: ${ratioPercent}%\" -ForegroundColor Cyan\r\n        Write-Host \"========================================================`n\" -ForegroundColor Cyan\r\n\r\n        # Use a separate dataset_name so checkpoints/logs don't overwrite your main results\r\n        $expName = \"${dataset}_${ratioTag}\"\r\n        $ckptDir = \"checkpoints/$expName\"\r\n        $logDir  = \"logs/$expName\"\r\n\r\n        # Copy the SSL encoder to the experiment checkpoint directory\r\n        New-Item -ItemType Directory -Force -Path $ckptDir | Out-Null\r\n        Copy-Item -Path $encoderPath -Destination \"$ckptDir/encoder_frozen.keras\" -Force\r\n\r\n        # Also copy the preprocessor from the base dataset if it exists\r\n        $basePreproc = \"checkpoints/$dataset/preprocessor.pkl\"\r\n        if (Test-Path $basePreproc) {\r\n            Copy-Item -Path $basePreproc -Destination \"$ckptDir/preprocessor.pkl\" -Force\r\n        }\r\n        # Copy task-specific preprocessors too\r\n        foreach ($t in @(\"dos\", \"port_scan\")) {\r\n            $taskPreproc = \"checkpoints/$dataset/preprocessor_${t}.pkl\"\r\n            if (Test-Path $taskPreproc) {\r\n                Copy-Item -Path $taskPreproc -Destination \"$ckptDir/preprocessor_${t}.pkl\" -Force\r\n            }\r\n        }\r\n\r\n        # Clear old task checkpoints for this experiment (but keep encoder + preprocessor)\r\n        foreach ($t in $tasks) {\r\n            $taskCkpt = \"$ckptDir/$t\"\r\n            if (Test-Path $taskCkpt) {\r\n                Remove-Item -Path $taskCkpt -Recurse -Force -ErrorAction SilentlyContinue\r\n            }\r\n        }\r\n        # Clear GPM for fresh continual learning per experiment\r\n        $gpmDir = \"$ckptDir/gpm\"\r\n        if (Test-Path $gpmDir) {\r\n            Remove-Item -Path $gpmDir -Recurse -Force -ErrorAction SilentlyContinue\r\n        }\r\n\r\n        # Determine task order: intrusion first (no GPM), then dos, then port_scan\r\n        $orderedTasks = @()\r\n        if ($tasks -contains \"intrusion\") { $orderedTasks += \"intrusion\" }\r\n        if ($tasks -contains \"dos\")       { $orderedTasks += \"dos\" }\r\n        if ($tasks -contains \"port_scan\") { $orderedTasks += \"port_scan\" }\r\n\r\n        foreach ($task in $orderedTasks) {\r\n            $taskConfig = $config[$task]\r\n            $epochs = if ($task -eq \"intrusion\") { $task_epochs } else { $gpm_epochs }\r\n\r\n            Write-Host \"  [TRAIN] $dataset / $task / ${ratioPercent}% labeled ($epochs epochs)\" -ForegroundColor Yellow\r\n            \r\n            # Build the train command\r\n            $trainCmd = \"python training/train_task.py --task $task $($taskConfig.train_args) --epochs $epochs --dataset_name $expName --label_ratio $ratio\"\r\n            Write-Host \"    > $trainCmd\" -ForegroundColor DarkGray\r\n            Invoke-Expression $trainCmd\r\n\r\n            Write-Host \"  [EVAL]  $dataset / $task / ${ratioPercent}% labeled\" -ForegroundColor Yellow\r\n\r\n            # Build the eval command\r\n            # For unsw, eval_args already includes --task and --test_csv\r\n            if ($dataset -eq \"unsw\") {\r\n                $evalCmd = \"python training/evaluate.py $($taskConfig.eval_args) --dataset_name $expName\"\r\n            } else {\r\n                $evalCmd = \"python training/evaluate.py --task $task $($taskConfig.eval_args) --dataset_name $expName\"\r\n            }\r\n            Write-Host \"    > $evalCmd\" -ForegroundColor DarkGray\r\n            Invoke-Expression $evalCmd\r\n\r\n            # Read the metrics JSON and add to results\r\n            $metricsFile = \"logs/$expName/eval/metrics_${task}.json\"\r\n            if (Test-Path $metricsFile) {\r\n                $metrics = Get-Content $metricsFile | ConvertFrom-Json\r\n                $allResults += [PSCustomObject]@{\r\n                    Dataset     = $dataset\r\n                    Task        = $task\r\n                    LabelRatio  = $ratioPercent\r\n                    Accuracy    = [math]::Round($metrics.accuracy, 4)\r\n                    F1_Weighted = [math]::Round($metrics.f1_weighted, 4)\r\n                    ROC_AUC     = [math]::Round($metrics.roc_auc, 4)\r\n                    PR_AUC      = [math]::Round($metrics.pr_auc, 4)\r\n                }\r\n                Write-Host \"    Acc=$([math]::Round($metrics.accuracy, 4)) F1=$([math]::Round($metrics.f1_weighted, 4)) AUC=$([math]::Round($metrics.roc_auc, 4))\" -ForegroundColor Green\r\n            } else {\r\n                Write-Host \"    [WARN] Metrics file not found: $metricsFile\" -ForegroundColor Red\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n# Print summary table\r\nWrite-Host \"`n\" -ForegroundColor White\r\nWrite-Host \"================================================================\" -ForegroundColor Green\r\nWrite-Host \"  LABEL RATIO EXPERIMENT RESULTS SUMMARY\" -ForegroundColor Green\r\nWrite-Host \"================================================================\" -ForegroundColor Green\r\n\r\nif ($allResults.Count -gt 0) {\r\n    $allResults | Format-Table -AutoSize\r\n\r\n    # Save results to CSV for easy import into paper\r\n    $csvPath = \"$resultsDir/label_ratio_results.csv\"\r\n    $allResults | Export-Csv -Path $csvPath -NoTypeInformation\r\n    Write-Host \"Results saved to: $csvPath\" -ForegroundColor Green\r\n\r\n    # Also save as JSON\r\n    $jsonPath = \"$resultsDir/label_ratio_results.json\"\r\n    $allResults | ConvertTo-Json -Depth 5 | Set-Content -Path $jsonPath\r\n    Write-Host \"Results saved to: $jsonPath\" -ForegroundColor Green\r\n} else {\r\n    Write-Host \"No results were collected.\" -ForegroundColor Red\r\n}\r\n\r\nWrite-Host \"`nAll label ratio experiments completed!\" -ForegroundColor Green\r\n
